/**
 * Serves a placeholder image for a mock sample — there is no fal access this
 * phase, so `mock-store.ts` never has real generated bytes to serve
 * (`docs/arc/bench/BRIEF.md`'s "Reality check"). Deterministic per
 * `(runId, alias, sampleIndex)` (same inputs, same SVG, always), so it is
 * safe to cache aggressively and safe for `next/image` to treat as a stable
 * source across re-renders.
 *
 * SVG, not a hand-rolled PNG encoder or an added image-generation
 * dependency — `next.config.ts` enables `images.dangerouslyAllowSVG` for
 * exactly this same-origin, self-authored source (never third-party or
 * user-supplied SVG, so the usual SVG/XSS concern the flag exists for does
 * not apply here).
 */
import { createHash } from "node:crypto";

const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

const hueFor = (identity: string): number => {
  const digest = createHash("sha256").update(identity).digest();
  return (digest[0] ?? 0) * (360 / 255);
};

export const dynamic = "force-dynamic";

export async function GET(
  request: Request,
  {
    params,
  }: { params: Promise<{ alias: string; runId: string; sampleIndex: string }> }
) {
  const { alias, runId, sampleIndex } = await params;
  const url = new URL(request.url);
  const width = clamp(Number(url.searchParams.get("w")) || 1024, 64, 2048);
  const height = clamp(Number(url.searchParams.get("h")) || 1024, 64, 2048);

  const hue = hueFor(`${runId}:${alias}:${sampleIndex}`);
  const fill = `hsl(${hue.toFixed(0)}, 38%, 30%)`;
  const accent = `hsl(${hue.toFixed(0)}, 45%, 46%)`;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="${width}" height="${height}" fill="${fill}" />
  <circle cx="${width * 0.5}" cy="${height * 0.42}" r="${Math.min(width, height) * 0.18}" fill="${accent}" opacity="0.6" />
  <text x="50%" y="${height * 0.6}" font-family="ui-monospace, monospace" font-size="${Math.max(14, Math.round(Math.min(width, height) / 22))}" fill="white" fill-opacity="0.92" text-anchor="middle">${alias}</text>
  <text x="50%" y="${height * 0.68}" font-family="ui-monospace, monospace" font-size="${Math.max(11, Math.round(Math.min(width, height) / 32))}" fill="white" fill-opacity="0.6" text-anchor="middle">mock · ${width}×${height} · sample ${sampleIndex}</text>
</svg>`;

  return new Response(svg, {
    headers: {
      "cache-control": "public, max-age=31536000, immutable",
      "content-type": "image/svg+xml",
    },
  });
}
